    window.saveEditStaff = async function(originalEmail) {
        var match = STAFF.find(s => (s.email || '').toLowerCase() === (originalEmail || '').toLowerCase());
        if (!match) { toast('Staff not found', 'alert-circle'); return; }
        var name = document.getElementById('es-name')?.value.trim();
        var email = document.getElementById('es-email')?.value.trim();
        var role = document.getElementById('es-role')?.value || 'staff';
        var pass = document.getElementById('es-pass')?.value.trim();
        if (!name) { toast('Name is required', 'alert-circle'); return; }
        match.name = name;
        match.email = email;
        match.role = role;
        if (pass) match.password = pass;

        saveOfflineStaff();
        if (window._serverAvailable) {
            try {
                await apiPut('/staff/' + (match._id || match.id), {
                    name: match.name,
                    email: match.email,
                    role: match.role,
                    ...(pass ? { password: match.password } : {})
                });
            } catch(e) {
                console.error('Failed to sync staff edit to server', e);
            }
        }
        
        renderStaffGrid();
        document.getElementById('modalOverlay').style.display = 'none';
        toast('Staff "' + name + '" updated', 'check-circle');
        logActivity('Staff Updated', 'Updated <strong>' + name + '</strong> account details');
    };

    async function deleteStaffMember(staff) {
        if (!confirm('Delete staff member "' + staff.name + '"?')) return;
        
        if (window._serverAvailable) {
            try {
                await fetchJson(API_BASE + '/staff/' + (staff._id || staff.id), { method: 'DELETE' });
            } catch(e) {
                console.error('Failed to sync staff delete to server', e);
            }
        }

        var idx = STAFF.indexOf(staff);
        if (idx !== -1) {
            STAFF.splice(idx, 1);
            saveOfflineStaff();
            renderStaffGrid();
            toast('"' + staff.name + '" deleted', 'check-circle');
            logActivity('Staff Deleted', 'Removed <strong>' + staff.name + '</strong> from staff');
        }
    }

    function renderStaffGrid() {
        const usersPanel = document.getElementById('staff-panel-users');
        if (!usersPanel) return;
        usersPanel.innerHTML = '<div class="grid grid-cols-2 gap-4" id="staff-users-grid"></div>';
        const grid = usersPanel.querySelector('#staff-users-grid');
        if (!grid) return;
        if (!STAFF.length) {
            grid.innerHTML = '<div class="text-center" style="color:var(--text-muted);grid-column:1/-1;padding:32px">No staff users yet.</div>';
            return;
        }
        STAFF.forEach(user => grid.appendChild(buildStaffCard(user)));
    }

    function updateReportStaffOptions() {
        var sel = document.getElementById('rpt-staff');
        if (!sel) return;
        var current = sel.value || 'all';
        sel.innerHTML = '<option value="all">All</option>';
        var names = new Set();
        STAFF.forEach(function(s) { if (s.name) names.add(s.name); });
        BILLS.forEach(function(b) { if (b.createdBy) names.add(b.createdBy); });
        names.forEach(function(name) {
            var opt = document.createElement('option');
            opt.value = name.toLowerCase();
            opt.textContent = name;
            sel.appendChild(opt);
        });
        sel.value = current;
        var actSel = document.getElementById('activity-filter-staff');
        if (actSel) {
            var actCurrent = actSel.value || '';
            actSel.innerHTML = '<option value="">All Staff</option>';
            names.forEach(function(name) {
                var opt = document.createElement('option');
                opt.value = name;
                opt.textContent = name;
                actSel.appendChild(opt);
            });
            actSel.value = actCurrent;
        }
    }

    function resetNewBillForm() {
        // Clear edit mode state
        EDIT_BILL_ID = null;
        const genBtn = document.getElementById('generateBillBtn');
        if (genBtn) {
            genBtn.innerHTML = '<i data-lucide="save" class="w-5 h-5"></i> Generate Bill';
            lucide.createIcons({ nodes: [genBtn] });
        }
        const editBanner = document.getElementById('edit-mode-banner');
        if (editBanner) editBanner.style.display = 'none';

        const fields = ['custName','custPhone','shipTo','billTo','billingNotes'];
        fields.forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
        const discount = document.getElementById('discountInput'); if (discount) discount.value = '0';
        // Always use the GST value from Settings (CGST + SGST) — never hardcode
        const gst = document.getElementById('gstInput'); if (gst) gst.value = (typeof getStoreGstInfo === 'function') ? getStoreGstInfo().percent : 18;
        document.getElementById('paidInput') && (document.getElementById('paidInput').value = '0');
        document.getElementById('cashPaidInput') && (document.getElementById('cashPaidInput').value = '0');
        document.getElementById('onlinePaidInput') && (document.getElementById('onlinePaidInput').value = '0');
        document.querySelectorAll('#paymentModePills button').forEach(btn => btn.classList.toggle('active', btn.dataset.payment === 'single'));
        updatePaymentModeFields();
        const container = document.getElementById('lineItemsContainer');
        if (container) {
            container.innerHTML = '';
            const defaultRows = [
                {name:'',qty:'',price:'',unit:''}
            ];
            defaultRows.forEach((item, index) => {
                const row = buildLineItemRow(item.name, item.qty, item.price, item.unit);
                container.appendChild(row);
            });
            updateLineItemNumbers();
        }
        recalcSummary();
    }

    /* ============================================================
       EDIT BILL ENGINE
       EDIT_BILL_ID: null = create mode, 'INV-XXXXX' = edit mode
    ============================================================ */
    let EDIT_BILL_ID = null;

    /** Shared helper: refresh all views after any bill mutation */
    function refreshAllViews() {
        renderBills();
        renderReportsFromBills();
        renderCustomerGrid();
        if (currentCustomerData) {
            refreshProfileStats();
            renderCustomerBills();
            renderLedger();
        }
        if (typeof renderDashboardRecentBills === 'function') renderDashboardRecentBills();
        if (typeof updateDashboardStats === 'function') updateDashboardStats();
        if (typeof window.renderInventoryTable === 'function') window.renderInventoryTable();
        if (typeof window.renderDashboardLowStock === 'function') window.renderDashboardLowStock();
    }

    /** PUT updated bill to server; falls back to in-memory update */
    async function updateBillOnServer(inv, updatedBill) {
        if (window._serverAvailable) {
            try {
                const result = await apiPut('/bills/' + encodeURIComponent(inv), updatedBill);
                return result;
            } catch(e) {
                console.error('updateBillOnServer PUT failed:', e);
            }
        }
        // Offline: persist to offline storage
        try {
            const s = localStorage.getItem('fp_bills_offline');
            const arr = s ? JSON.parse(s) : [];
            const idx = arr.findIndex(b => b.inv === inv);
            if (idx >= 0) arr[idx] = updatedBill;
            else arr.push(updatedBill);
            localStorage.setItem('fp_bills_offline', JSON.stringify(arr));
        } catch(e) { console.error('updateBillOnServer offline fallback:', e); }
    }

    /**
     * Open an existing bill in edit mode.
     * Pre-fills the billing form and sets EDIT_BILL_ID.
     */
    window.openEditBill = function(invId) {
        const bill = BILLS.find(b => b.inv === invId)
                  || (currentCustomerData && currentCustomerData.bills.find(b => b.inv === invId));
        if (!bill) { toast('Bill not found', 'alert-circle'); return; }

        // Full live bill from BILLS array (has all fields)
        const liveBill = BILLS.find(b => b.inv === invId) || bill;

        // Close any open modal first
        if (typeof closeModal === 'function') closeModal();

        if (liveBill.type === 'GST') {
            window.openEditGstBill(invId);
            return;
        }

        // Navigate to billing page
        goto('new-bill');

        // Small delay so DOM is visible before we populate
        setTimeout(() => {
            // Reset to clean state (this also clears any prior EDIT_BILL_ID)
            resetNewBillForm();

            // Set edit mode AFTER reset
            EDIT_BILL_ID = invId;

            // Show edit banner
            const editBanner = document.getElementById('edit-mode-banner');
            if (editBanner) { editBanner.style.display = 'flex'; }
            const editInvId = document.getElementById('edit-mode-inv-id');
            if (editInvId) editInvId.textContent = invId;

            // Switch button label
            const genBtn = document.getElementById('generateBillBtn');
            if (genBtn) {
                genBtn.innerHTML = '<i data-lucide="save" class="w-5 h-5"></i> Save Changes';
                lucide.createIcons({ nodes: [genBtn] });
            }

            // --- Populate customer fields ---
            const setVal = (id, val) => { const el = document.getElementById(id); if (el) el.value = val || ''; };
            setVal('custName',     liveBill.customer);
            setVal('custPhone',    liveBill.phone);
            setVal('shipTo',       liveBill.shipTo);
            setVal('billTo',       liveBill.billTo);
            setVal('billingNotes', liveBill.notes || '');
            setVal('discountInput', liveBill.discount || 0);
            setVal('gstInput',     liveBill.gstPercent || liveBill.gst_percent || (typeof getStoreGstInfo === 'function' ? getStoreGstInfo().percent : 18));

            // --- Populate payment fields ---
            const paid = parseFloat(liveBill.paid) || 0;
            setVal('paidInput', paid);
            setVal('cashPaidInput', 0);
            setVal('onlinePaidInput', 0);

            // --- Populate line items ---
            const container = document.getElementById('lineItemsContainer');
            if (container) {
                container.innerHTML = '';
                let parsedItems = liveBill.items || [];
                if (typeof parsedItems === 'string') {
                    try { parsedItems = JSON.parse(parsedItems); } catch(e) { parsedItems = []; }
                }
                if (!parsedItems.length) parsedItems = [{ name: '', qty: '', price: '', unit: '' }];
                parsedItems.forEach(item => {
                    const row = buildLineItemRow(
                        item.name || '',
                        (item.qty === undefined || item.qty === null || item.qty === '') ? '' : item.qty,
                        (item.price === undefined || item.price === null || item.price === '') ? '' : item.price,
                        item.unit  || ''
                    );
                    container.appendChild(row);
                });
                // Always add one blank row at the end
                container.appendChild(buildLineItemRow('', '', '', ''));
                updateLineItemNumbers();
            }

            recalcSummary();
            lucide.createIcons();
            toast('Editing ' + invId + ' — make changes and click Save Changes', 'pencil');
        }, 80);
    };

    /** Cancel edit — reset form and go back to Bills */
    window.cancelEditBill = function() {
        EDIT_BILL_ID = null;
        resetNewBillForm();
        goto('bills');
        toast('Edit cancelled', 'x-circle');
    };

    /**
     * Save an edited bill — called when generateBillBtn is clicked in edit mode.
     * Preserves inv, date, createdBy, createdAt.
     * Handles inventory: restore original → deduct updated.
     */
    async function saveEditedBill() {
        const custName = document.getElementById('custName')?.value?.trim();
        const custPhone = document.getElementById('custPhone')?.value?.trim();
        const shipTo = document.getElementById('shipTo')?.value?.trim();
        const billTo = document.getElementById('billTo')?.value?.trim();
        const notes = document.getElementById('billingNotes')?.value?.trim();

        if (!custName) { toast('Please enter customer name', 'alert-circle'); return; }

        // Find original bill
        const originalBillIdx = BILLS.findIndex(b => b.inv === EDIT_BILL_ID);
        if (originalBillIdx === -1) { toast('Original bill not found', 'alert-circle'); return; }
        const originalBill = BILLS[originalBillIdx];

        // Read all line items
        const items = [];
        document.querySelectorAll('#lineItemsContainer .li-row').forEach(row => {
            const name = row.querySelector('.li-name')?.value?.trim() || '';
            const qty = parseFloat(row.querySelector('.li-qty')?.value) || 0;
            const price = parseFloat(row.querySelector('.li-price')?.value) || 0;
            const unit = row.querySelector('.li-unit')?.value || '';
            const amountText = row.querySelector('.li-amount')?.textContent || '';
            const amount = parseFloat(amountText.replace(/[^0-9.-]+/g,'')) || (qty * price);
            if (name) items.push({ name, qty, price, unit, amount });
        });

        const subtotal = parseFloat((document.getElementById('previewSubtotal')?.textContent || '').replace(/[^0-9.-]+/g,'')) || 0;
        const gstPercent = parseFloat(document.getElementById('gstInput')?.value) || 0;
        const gstAmount = parseFloat((document.getElementById('previewGst')?.textContent || '').replace(/[^0-9.-]+/g,'')) || 0;
        const total = parseFloat((document.getElementById('previewTotal')?.textContent || '').replace(/[^0-9.-]+/g,'')) || (subtotal + gstAmount);
        const discount = parseFloat(document.getElementById('discountInput')?.value) || 0;
        const paidInfo = getTotalPaid();
        const paid = paidInfo.total;
        const status = paid >= total ? 'Paid' : (paid > 0 ? 'Partial' : 'Outstanding');
        const type = detectType(items.map(i => i.name).join(' ')) === 'counter' ? 'Counter' : 'Normal';

        // Build updated bill — preserve all original metadata
        const updatedBill = Object.assign({}, originalBill, {
            customer: custName,
            phone: custPhone,
            shipTo,
            billTo,
            notes,
            items,
            subtotal,
            discount,
            gst: gstAmount,
            gstPercent,
            total,
            paid,
            status,
            type
        });
        // Stamp update fields without overwriting creation fields
        stampRecord(updatedBill, true);

        // --- Inventory: restore original, then deduct updated ---
        if (typeof window.restoreInventoryFromBill === 'function') {
            window.restoreInventoryFromBill(originalBill.items || []);
        }
        if (typeof window.deductInventoryFromBill === 'function') {
            window.deductInventoryFromBill(items);
        }

        // --- Update BILLS array in-place ---
        BILLS[originalBillIdx] = updatedBill;

        // --- Persist ---
        try {
            await updateBillOnServer(EDIT_BILL_ID, updatedBill);
        } catch(e) {
            console.error('saveEditedBill persist error:', e);
        }

        // If the bill was originally offline, keep it marked so
        if (originalBill._offline) {
            updatedBill._offline = true;
            try {
                localStorage.setItem('fp_bills_offline',
                    JSON.stringify(BILLS.filter(b => b._offline)));
            } catch(e) {}
        }

        // Capture inv before reset clears it
        const savedInv = EDIT_BILL_ID;

        // --- Reset form ---
        resetNewBillForm(); // also clears EDIT_BILL_ID

        // --- Refresh all views ---
        refreshAllViews();

        // --- Log activity ---
        logActivity('Bill Edited', 'Updated <span class="font-mono font-bold" style="color:var(--primary)">' + savedInv + '</span> for ' + custName + ' · ₹ ' + Math.round(total).toLocaleString('en-IN'));

        // --- Items HTML for modal ---
        const itemsHtml = items.map(item => {
            const detail = `${item.qty || 0} ${item.unit || ''} × ₹${(item.price || 0).toLocaleString('en-IN')} = ₹${(item.amount || 0).toLocaleString('en-IN')}`;
            return `<div class="flex justify-between items-center py-1 text-sm border-b border-gray-100 last:border-b-0" style="border-color:var(--border)">
                        <span class="font-medium">${item.name}</span>
                        <span class="tabular-nums text-xs" style="color:var(--text-muted)">${detail}</span>
                    </div>`;
        }).join('');

        const totalText = document.getElementById('previewTotal')?.textContent || ('₹ ' + total.toLocaleString('en-IN'));

        // --- Success modal ---
        openModal(`
            <div class="font-serif text-2xl font-bold mb-1">Bill Updated!</div>
            <div class="text-sm mb-5" style="color:var(--text-muted)">Changes saved to invoice <span class="font-mono font-bold" style="color:var(--primary)">${savedInv}</span></div>
            <div style="background:var(--surface-tint);border:1px solid var(--border);border-radius:14px;padding:18px;margin-bottom:20px">
                <div class="flex justify-between mb-2"><span style="color:var(--text-muted)">Invoice #</span><span class="font-mono font-bold" style="color:var(--primary)">${savedInv}</span></div>
                <div class="flex justify-between mb-2"><span style="color:var(--text-muted)">Customer</span><span class="font-semibold">${custName}</span></div>
                <div class="flex justify-between mb-2"><span style="color:var(--text-muted)">Contact</span><span class="font-mono">${custPhone || '—'}</span></div>
                <div class="mt-3 pt-3 border-t" style="border-color:var(--border)">
                    <div class="text-xs font-bold uppercase tracking-widest mb-2" style="color:var(--text-muted)">Items</div>
                    <div class="max-h-36 overflow-y-auto space-y-1 pr-1">${itemsHtml || '<div class="text-xs" style="color:var(--text-subtle)">No items</div>'}</div>
                </div>
                <div class="flex justify-between mt-3 pt-3 border-t" style="border-color:var(--border)"><span style="color:var(--text-muted)">Total</span><span class="font-serif font-bold text-xl" style="color:var(--primary)">${totalText}</span></div>
            </div>
            <div class="grid grid-cols-2 gap-2 mb-3">
                <button class="btn btn-secondary text-sm" onclick="window.printBillByInvoice('${savedInv}');closeModal()"><i data-lucide="printer" class="w-4 h-4"></i> Print</button>
                <button class="btn btn-secondary text-sm" onclick="window.downloadBillPDF('${savedInv}');closeModal()"><i data-lucide="download" class="w-4 h-4"></i> PDF</button>
            </div>
            <button class="btn btn-primary w-full" onclick="closeModal()"><i data-lucide="check" class="w-4 h-4"></i> Done</button>
        `);
        toast('Bill ' + savedInv + ' updated', 'check-circle');
    }

    async function initializeApp() {
        // One-time data reset: clear any old mock/demo data from previous sessions
        const RESET_VERSION = 'fp_reset_v3';
        if (!localStorage.getItem(RESET_VERSION)) {
            ['fp_inventory_items','fp_shortcut_items','fp_bills_offline','fp_expenses_offline','fp_dropdown_settings','fp_customers_offline','fp_customer_payments','fp_staff_offline','fp_activity_log'].forEach(k => localStorage.removeItem(k));
            localStorage.setItem(RESET_VERSION, '1');
        }

        await loadServerData();
        // load any locally-saved offline bills to merge with server data
        loadOfflineBills();
        // load any offline-saved customers, staff, and activity log
        loadOfflineCustomers();
        loadOfflineStaff();
        loadActivityLog();
        // rebuild customers from bills if any customers are missing
        BILLS.forEach(b => {
            if (b.customer && !CUSTOMERS.find(c => (c.name || '').toLowerCase() === (b.customer || '').toLowerCase())) {
                CUSTOMERS.push({ name: b.customer, phone: b.phone || '' });
            }
        });
        if (CUSTOMERS.length) saveOfflineCustomers();
        // load any offline-saved expenses
        loadOfflineExpenses();
        renderCustomerGrid();
        renderStaffGrid();
        renderBills();
        renderReportsFromBills();
        renderExpenseTable();
        renderExpensesReport();
        updateReportStaffOptions();
        
        // Load settings and inventory data
        if (typeof loadShortcutItems === 'function') loadShortcutItems();
        if (typeof loadDropdownSettings === 'function') loadDropdownSettings();
        if (typeof updateGstUnitsDatalist === 'function') updateGstUnitsDatalist();
        if (typeof loadInventoryData === 'function') loadInventoryData();
        if (typeof renderDashboardRecentBills === 'function') renderDashboardRecentBills(); if (typeof updateDashboardStats === 'function') updateDashboardStats();
        if (typeof renderInventoryTable === 'function') renderInventoryTable();
        if (typeof renderDashboardLowStock === 'function') renderDashboardLowStock();
        if (typeof updatePOSDatalist === 'function') updatePOSDatalist();
        if (typeof updateCustomerSuggestions === 'function') updateCustomerSuggestions();
        renderActivityLog();

        // Restore user session and active page from localStorage
        const savedUser = localStorage.getItem('fp_current_user');
        if (savedUser) {
            try {
                const user = JSON.parse(savedUser);
                CURRENT_USER = user;
                setRole(user.role, null, user);
                document.body.classList.remove('logged-out');
                const loginPage = document.getElementById('page-login');
                if (loginPage) loginPage.style.display = 'none';
                const appShell = document.getElementById('appShell');
                if (appShell) appShell.style.display = 'flex';
                
                const activePage = localStorage.getItem('fp_active_page') || 'dashboard';
                goto(activePage);
            } catch(e) {
                console.error('Failed to restore user session', e);
            }
        }

        // Start 3-second auto-sync polling loop
        startAutoSync();

        // Auto-login utility for testing and subagent runs
        const urlParams = new URLSearchParams(window.location.search);
        if (urlParams.get('autologin') === 'true') {
            setTimeout(() => {
                loginSuccess('admin', null);
                goto('gst-billing');
            }, 300);
        }
    }

    let lastSyncHash = '';
    function startAutoSync() {
        setInterval(async () => {
            if (!window._serverAvailable) return;
            try {
                const [bills, customers, staff, expenses, inventory, activity, storeSettings] = await Promise.all([
                    apiGet('/bills'),
                    apiGet('/customers'),
                    apiGet('/staff'),
                    apiGet('/expenses'),
                    apiGet('/inventory'),
                    apiGet('/activity'),
                    apiGet('/settings/store_settings').catch(() => null)
                ]);
                
                const currentHash = JSON.stringify({
                    bills: bills.map(b => b.inv),
                    customers: customers.map(c => ({ id: c._id || c.id, archived: c.archived })),
                    staff: staff.map(s => ({ id: s._id || s.id, active: s.active })),
                    expenses: expenses.map(e => e._id || e.id),
                    inventory: inventory.map(i => ({ id: i._id || i.id, qty: i.qty })),
                    activity: activity.length,
                    settings: storeSettings ? storeSettings.name : ''
                });

                if (lastSyncHash && lastSyncHash !== currentHash) {
                    console.log('Change detected in auto-sync. Redrawing views...');
                    BILLS.length = 0; BILLS.push(...(Array.isArray(bills) ? bills : []));
                    CUSTOMERS.length = 0; CUSTOMERS.push(...(Array.isArray(customers) ? customers : []));
                    STAFF.length = 0; STAFF.push(...(Array.isArray(staff) ? staff : []));
                    EXPENSE_ENTRIES.length = 0; EXPENSE_ENTRIES.push(...(Array.isArray(expenses) ? expenses : []));
                    if (storeSettings) {
                        STORE_SETTINGS = { ...STORE_SETTINGS, ...storeSettings };
                        populateSettingsUI();
                    }
                    if (Array.isArray(inventory) && inventory.length) {
                        INVENTORY_ITEMS.length = 0;
                        INVENTORY_ITEMS.push(...inventory);
                    }
                    if (Array.isArray(activity) && activity.length) {
                        ACTIVITY_LOG.length = 0;
                        ACTIVITY_LOG.push(...activity);
                    }

                    renderCustomerGrid();
                    renderStaffGrid();
                    renderBills();
                    renderReportsFromBills();
                    renderExpenseTable();
                    renderExpensesReport();
                    updateReportStaffOptions();
                    if (typeof renderDashboardRecentBills === 'function') renderDashboardRecentBills();
                    if (typeof updateDashboardStats === 'function') updateDashboardStats();
                    if (typeof renderInventoryTable === 'function') renderInventoryTable();
                    if (typeof renderDashboardLowStock === 'function') renderDashboardLowStock();
                    if (typeof updatePOSDatalist === 'function') updatePOSDatalist();
                    if (typeof updateCustomerSuggestions === 'function') updateCustomerSuggestions();
                    renderActivityLog();
                }
                lastSyncHash = currentHash;
            } catch(e) {
                console.error('Error during auto-sync', e);
            }
        }, 3000);
    }

