    window.downloadCustomerHistoryCSV = function() {
        if (!currentCustomerData) return;
        const name = currentCustomerData.name;
        const phone = currentCustomerData.phone || '—';
        const bills = currentCustomerData.bills || [];

        const resolvedBills = bills.map(cb => {
            let bill = BILLS.find(b => b.inv === cb.inv);
            if (!bill) {
                const total = parseFloat(String(cb.total).replace(/[^0-9.-]+/g,'')) || 0;
                const paid = parseFloat(String(cb.paid).replace(/[^0-9.-]+/g,'')) || 0;
                bill = {
                    inv: cb.inv,
                    date: cb.date,
                    dateDisplay: cb.dateDisplay,
                    customer: name,
                    phone: phone,
                    total: total,
                    paid: paid,
                    status: cb.status || (total - paid <= 0 ? 'paid' : paid > 0 ? 'partial' : 'outstanding'),
                    type: cb.type || 'Normal',
                    createdBy: 'System',
                    subtotal: total / getStoreGstInfo().factor,
                    gstPercent: getStoreGstInfo().percent,
                    gst: total - (total / getStoreGstInfo().factor),
                    items: [
                        { name: 'Printing Services (Standard)', qty: 1, unit: 'Job', price: total / getStoreGstInfo().factor, amount: total / getStoreGstInfo().factor }
                    ]
                };
            }
            return bill;
        });

        const esc = (val) => {
            if (val === null || val === undefined) return '';
            let s = String(val).replace(/"/g, '""');
            if (s.includes(',') || s.includes('\n') || s.includes('"')) return `"${s}"`;
            return s;
        };

        const lines = [];
        lines.push('Customer History Statement');
        lines.push('Customer Name,' + esc(name));
        lines.push('Phone,' + esc(phone));
        lines.push('');
        lines.push('Invoice Number,Date,Status,Item Description,Quantity,Unit,Rate,Line Total,Invoice Total,Invoice Paid,Invoice Due');

        resolvedBills.forEach(bill => {
            let parsedItems = bill.items || [];
            if (typeof parsedItems === 'string') {
                try { parsedItems = JSON.parse(parsedItems); } catch(e) { parsedItems = []; }
            }
            if (!parsedItems.length) {
                const totalVal = parseFloat(String(bill.total).replace(/[^0-9.-]+/g,'')) || 0;
                parsedItems = [{ name: 'Printing Services (Standard)', qty: 1, unit: 'Job', price: totalVal / getStoreGstInfo().factor, amount: totalVal / getStoreGstInfo().factor }];
            }

            const total = parseFloat(String(bill.total).replace(/[^0-9.-]+/g,'')) || 0;
            const paid = parseFloat(String(bill.paid).replace(/[^0-9.-]+/g,'')) || 0;
            const due = total - paid;
            const status = bill.status || 'outstanding';
            const dateStr = bill.dateDisplay || formatShortDate(bill.date);

            parsedItems.forEach((item, idx) => {
                const isFirstRow = idx === 0;
                const invCol       = isFirstRow ? esc(bill.inv) : '';
                const dateCol      = isFirstRow ? esc(dateStr) : '';
                const statusCol    = isFirstRow ? esc(status) : '';
                const invTotalCol  = isFirstRow ? total.toFixed(2) : '';
                const invPaidCol   = isFirstRow ? paid.toFixed(2) : '';
                const invDueCol    = isFirstRow ? due.toFixed(2) : '';

                const lineTotal = (parseFloat(item.amount) || 0).toFixed(2);
                const rate = (parseFloat(item.price) || 0).toFixed(2);

                lines.push([
                    invCol,
                    dateCol,
                    statusCol,
                    esc(item.name),
                    item.qty || 0,
                    esc(item.unit || 'pcs'),
                    rate,
                    lineTotal,
                    invTotalCol,
                    invPaidCol,
                    invDueCol
                ].join(','));
            });
        });

        const csvString = lines.join('\n');

        const blob = new Blob(['﻿' + csvString], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `${name.replace(/\s+/g, '_')}_history.csv`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
        toast('History CSV Downloaded', 'check-circle');
    };

