    // Generate consecutive GST invoice numbers
    window.getNextGstInvoiceNo = function() {
        let maxNum = 0;
        BILLS.forEach(b => {
            if (b.type === 'GST' && b.inv && b.inv.startsWith('GST-')) {
                const parts = b.inv.split('-');
                const num = parseInt(parts[1]);
                if (!isNaN(num) && num > maxNum) maxNum = num;
            }
        });
        return 'GST-' + String(maxNum + 1).padStart(3, '0');
    }

    // Generate consecutive normal invoice numbers
    window.getNextNormalInvoiceNo = function() {
        let maxNum = 0;
        BILLS.forEach(b => {
            if (b.type !== 'GST' && b.inv && b.inv.startsWith('INV-')) {
                const parts = b.inv.split('-');
                const num = parseInt(parts[1]);
                if (!isNaN(num) && num > maxNum) maxNum = num;
            }
        });
        return 'INV-' + String(maxNum + 1).padStart(3, '0');
    }

    // Numbers in words helper (Indian format)
    window.convertNumberToWords = function(num) {
        if (num === 0) return 'Zero Rupees Only';
        
        let parts = String(parseFloat(num).toFixed(2)).split('.');
        let rupees = parseInt(parts[0]) || 0;
        let paise = parseInt(parts[1]) || 0;
        
        let words = '';
        
        if (rupees > 0) {
            words += convertPart(rupees) + ' Rupees';
        }
        
        if (paise > 0) {
            if (rupees > 0) words += ' and ';
            words += convertPart(paise) + ' Paise';
        }
        
        return words + ' Only';
    }

    function convertPart(amount) {
        const singleDigits = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine"];
        const doubleDigits = ["Ten", "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"];
        const tensDigits = ["", "Ten", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"];
        
        if (amount === 0) return "";
        
        function helper(n) {
            let str = "";
            if (n >= 100) {
                str += singleDigits[Math.floor(n / 100)] + " Hundred ";
                n %= 100;
            }
            if (n >= 20) {
                str += tensDigits[Math.floor(n / 10)] + " ";
                n %= 10;
            } else if (n >= 10) {
                str += doubleDigits[n - 10] + " ";
                n = 0;
            }
            if (n > 0) {
                str += singleDigits[n] + " ";
            }
            return str.trim();
        }
        
        let result = "";
        if (amount >= 10000000) {
            result += helper(Math.floor(amount / 10000000)) + " Crore ";
            amount %= 10000000;
        }
        if (amount >= 100000) {
            result += helper(Math.floor(amount / 100000)) + " Lakh ";
            amount %= 100000;
        }
        if (amount >= 1000) {
            result += helper(Math.floor(amount / 1000)) + " Thousand ";
            amount %= 1000;
        }
        if (amount > 0) {
            result += helper(amount);
        }
        
        return result.trim();
    }

